import{_ as t,o as n,c as i,ah as o}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Admissions Advisor","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/equipe/conseiller.md","filePath":"src/en/guide/equipe/conseiller.md"}'),s={name:"en/guide/equipe/conseiller.md"};function a(r,e,d,h,l,c){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="admissions-advisor" tabindex="-1">Admissions Advisor <a class="header-anchor" href="#admissions-advisor" aria-label="Permalink to &quot;Admissions Advisor&quot;">​</a></h1><p>The Admissions Advisor handles candidatures: they hold the interview, oversee the test and give the decision. The role is assigned by the Administrator. Your work takes place in <strong>Journeys → Candidatures</strong>.</p><h2 id="the-candidature-queue" tabindex="-1">The candidature queue <a class="header-anchor" href="#the-candidature-queue" aria-label="Permalink to &quot;The candidature queue&quot;">​</a></h2><p>Candidatures arrive in a <strong>shared queue</strong>. Three filters help you find your way: <strong>Everyone</strong>, <strong>Not taken</strong>, <strong>Mine</strong>. You can also search by name or e-mail, and filter by program and status (in progress, admitted, refused).</p><p>Each line shows the current step (application, interview, test, decision), its due date, the advisor in charge, and the <strong>Minor</strong> and <strong>Overdue</strong> markers.</p><h2 id="taking-a-file-in-charge" tabindex="-1">Taking a file in charge <a class="header-anchor" href="#taking-a-file-in-charge" aria-label="Permalink to &quot;Taking a file in charge&quot;">​</a></h2><p>Open the candidature and click <strong>Take this candidature</strong>: you become the <strong>advisor in charge</strong>. A file can only be taken once. Only the advisor in charge can close the interview and give the decision. The Pedagogical Coordinator does not take files, but can <strong>reassign</strong> one to another advisor, who then receives the reminders.</p><p>The page gathers everything: the candidate, the requested format, their motivation, their attachments (which you can download), the steps with their dates, and the history of their <strong>previous candidatures</strong>. A <strong>minor</strong> candidate is flagged: their enrolment will require a legal guardian&#39;s signature.</p><h2 id="the-interview" tabindex="-1">The interview <a class="header-anchor" href="#the-interview" aria-label="Permalink to &quot;The interview&quot;">​</a></h2><p>Hold the interview <strong>within 5 working days</strong> of the application (Monday to Friday, excluding public holidays entered by the Administrator). Then click <strong>Record the interview</strong>, write the <strong>report</strong>, which stays internal, and <strong>Close the interview</strong>.</p><p>Closing <strong>opens the test</strong>: the candidate receives the link by e-mail, provided the program&#39;s question bank is validated. Otherwise, the test waits; you click <strong>Send the test link</strong> once the bank is validated.</p><h2 id="the-test" tabindex="-1">The test <a class="header-anchor" href="#the-test" aria-label="Permalink to &quot;The test&quot;">​</a></h2><p>The candidate takes the test without an account, with a single-use link valid for 48 hours. They have 2 attempts of 45 minutes, on 10 questions. Their score is shown to them on submission. The page gives you, for each link, its attempts, their state (in progress, not submitted) and the score out of 10.</p><p>The 6-out-of-10 threshold is <strong>indicative</strong>: the file goes to decision <strong>whatever the score</strong>. A passed attempt closes the test.</p><p>If the link <strong>expires</strong>, or if attempts are used up for lack of time, you are reminded once. Nothing is automatic: it is for you to choose.</p><ul><li><strong>Send a new link</strong> resets the attempts (the number of resends is kept);</li><li><strong>Close the test</strong> moves the file to decision.</li></ul><h2 id="the-decision" tabindex="-1">The decision <a class="header-anchor" href="#the-decision" aria-label="Permalink to &quot;The decision&quot;">​</a></h2><p>Give the decision <strong>within 3 working days</strong> of the test: <strong>Decide</strong>, then choose <strong>Admitted</strong> or <strong>Refused</strong> and enter the <strong>reason</strong>, mandatory. The reason stays internal; the candidate is notified by e-mail and receives their decision letter.</p><ul><li><strong>Admitted.</strong> Choose the candidate&#39;s <strong>cohort</strong>. The list only offers cohorts not yet started, with seats and the candidate&#39;s format. If none fits, leave &quot;No cohort&quot;: the Coordinator will place the learner later. The account becomes Learner and their enrolment is created.</li><li><strong>Refused.</strong> The file is closed, with no payment or access to Sève. The candidate cannot reapply for 7 days.</li></ul><h2 id="reminders" tabindex="-1">Reminders <a class="header-anchor" href="#reminders" aria-label="Permalink to &quot;Reminders&quot;">​</a></h2><p>A daily task reminds you, once per step, when a deadline is passed: interview not held, test not taken, decision not given. The reminder goes to the advisor in charge, or to <strong>all advisors</strong> as long as nobody has taken the file. It is sent by e-mail, and on Sève and WhatsApp if your account and phone allow.</p>',21)])])}const p=t(s,[["render",a]]);export{u as __pageData,p as default};
